files['qseries_v2/oracle_predictive_discovery/opd_061_realtime_kalshi_anchor_tap.py']='from pathlib import Path\nimport json,os\nfrom qseries_v2.oracle_production_hardening.oph_019_postgresql_universal_ingestion_queue import connect\nexecution_authority=False\nprobability_enabled=False\ndirection_enabled=False\npublication_allowed=False\n\ndef _asset(ticker):\n    u=str(ticker).upper()\n    if "BTC" in u:return "BTC"\n    if "ETH" in u:return "ETH"\n    if "SOL" in u:return "SOL"\n    return None\n\ndef _canonical_highwater(root):\n    with connect(Path(root),autocommit=False) as c:\n        with c.cursor() as q:\n            q.execute("SET TRANSACTION READ ONLY")\n            q.execute("SET LOCAL statement_timeout=\'5000ms\'")\n            q.execute("SELECT sequence_number FROM public.oracle_canonical_observations ORDER BY sequence_number DESC LIMIT 1")\n            row=q.fetchone()\n        c.rollback()\n    return int(row[0]) if row else 0\n\ndef freeze_trade(raw,received_at,observation_id,root=None):\n    if not isinstance(raw,dict) or str(raw.get("type",""))!="trade":return None\n    msg=raw.get("msg") or {}\n    ticker=str(msg.get("market_ticker") or msg.get("ticker") or "").strip()\n    asset=_asset(ticker)\n    if not asset:return None\n    price=None\n    for k in ("yes_price_dollars","price_dollars","last_price_dollars"):\n        try:\n            v=float(msg[k])\n            if 0.0<=v<=1.0:price=v;break\n        except Exception:pass\n    if price is None:return None\n    root=Path(root or Path.cwd())\n    t=float(received_at.timestamp())\n    boundary=_canonical_highwater(root)\n    row={"schema_version":"OPD-061","anchor_id":str(observation_id),"ticker":ticker,\n         "asset":asset,"observed_epoch":t,"anchor_price":price,\n         "anchor_sequence_boundary":boundary,\n         "anchor_sequence_basis":"CANONICAL_HIGHWATER_AT_FREEZE",\n         "kalshi_state":{"sequence_number":boundary,"event_epoch":t,"trade_price":price,\n         "yes_bid":msg.get("yes_bid_dollars"),"yes_ask":msg.get("yes_ask_dollars"),\n         "spread":None,"yes_bid_size":msg.get("yes_bid_size"),"yes_ask_size":msg.get("yes_ask_size"),\n         "last_trade_size":msg.get("count_fp"),"volume":None,"open_interest":None,\n         "observation_type":"trade","event_time_path":"LIVE_RECEIVED_AT"},"post_freeze":True}\n    p=root/"runtime"/"predictive_data"/"opd_061_live_anchor_spool.jsonl"\n    p.parent.mkdir(parents=True,exist_ok=True)\n    with p.open("a",encoding="utf-8") as f:\n        f.write(json.dumps(row,sort_keys=True,separators=(",",":"))+"\\n");f.flush();os.fsync(f.fileno())\n    return row\n'
files['qseries_v2/oracle_predictive_discovery/opd_063_multi_horizon_prospective_intake.py']='from pathlib import Path\nfrom qseries_v2.oracle_predictive_discovery.opd_062_strict_asof_live_world_state import assemble\nfrom qseries_v2.oracle_predictive_discovery.opd_042_live_state_to_prospective_intake_bridge import intake_world_state\nfrom qseries_v2.oracle_predictive_discovery.opd_043_exact_durable_maturity_queue import rebuild_exact\nexecution_authority=False\nprobability_enabled=False\ndirection_enabled=False\npublication_allowed=False\nHORIZONS=(5,15,30,60,300,900,3600)\n\ndef intake_anchor(anchor,state_root=None,repo_root=None,assembler=None,rebuild_queue=True):\n    state_root=Path(state_root or Path.cwd());repo_root=Path(repo_root or Path.cwd())\n    extra=(assembler or assemble)(anchor,repo_root)\n    out=[]\n    for h in HORIZONS:\n        s={"anchor_id":anchor["anchor_id"],"ticker":anchor["ticker"],"observed_epoch":anchor["observed_epoch"],\n           "horizon_seconds":h,"anchor_price":anchor["anchor_price"],"kalshi_state":anchor["kalshi_state"],\n           "anchor_sequence_boundary":anchor.get("anchor_sequence_boundary"),\n           "anchor_sequence_basis":anchor.get("anchor_sequence_basis"),\n           "coinbase_hf_state":extra["coinbase_hf_state"],"crypto_condition_state":extra["crypto_condition_state"],\n           "learned_state":extra["learned_state"]}\n        out.append(intake_world_state(s,state_root,repo_root))\n    if rebuild_queue:rebuild_exact(state_root)\n    return out\n'
files['qseries_v2/oracle_predictive_discovery/opd_042_live_state_to_prospective_intake_bridge.py']='from pathlib import Path\nfrom qseries_v2.oracle_predictive_discovery.opd_041_exact_live_token_materializer import materialize_exact_live_tokens\nfrom qseries_v2.oracle_predictive_data.opd_032_prospective_state_intake_ledger import observe\nexecution_authority=False\nprobability_enabled=False\ndirection_enabled=False\npublication_allowed=False\nREQ=("anchor_id","ticker","observed_epoch","horizon_seconds","anchor_price","kalshi_state","coinbase_hf_state","crypto_condition_state","learned_state")\nFORBIDDEN={"future_target","future_return","mfe","mae","hit_plus_05","hit_minus_05","hit_plus_10","hit_minus_10","resolution_epoch"}\n\ndef snapshot_from_world_state(state_at_t,repo_root=None):\n    if not isinstance(state_at_t,dict):raise TypeError("state_at_t must be dict")\n    if FORBIDDEN.intersection(state_at_t):raise ValueError("POST_T_OR_OUTCOME_FIELD_REJECTED")\n    if any(k not in state_at_t for k in REQ):raise ValueError("MISSING_EXACT_WORLD_STATE_FIELD")\n    repo_root=Path(repo_root or Path.cwd())\n    tokens=materialize_exact_live_tokens(repo_root,state_at_t)\n    return {"anchor_id":state_at_t["anchor_id"],"ticker":state_at_t["ticker"],\n            "observed_epoch":float(state_at_t["observed_epoch"]),"horizon_seconds":int(state_at_t["horizon_seconds"]),\n            "anchor_price":state_at_t["anchor_price"],"tokens":list(tokens),\n            "anchor_sequence_boundary":state_at_t.get("anchor_sequence_boundary"),\n            "anchor_sequence_basis":state_at_t.get("anchor_sequence_basis")}\n\ndef intake_world_state(state_at_t,state_root=None,repo_root=None):\n    state_root=Path(state_root or Path.cwd());repo_root=Path(repo_root or Path.cwd())\n    return observe(snapshot_from_world_state(state_at_t,repo_root),state_root)\n'
files['qseries_v2/oracle_predictive_data/opd_032_prospective_state_intake_ledger.py']='from pathlib import Path\nimport hashlib,json\nFORBIDDEN={"future_target","future_return","mfe","mae","hit_plus_05","hit_minus_05","hit_plus_10","hit_minus_10","resolution_epoch"}\n\ndef _canon(x):return json.dumps(x,sort_keys=True,separators=(",",":"))\ndef _paths(root):\n    rt=Path(root)/"runtime"/"predictive_data";return rt,rt/"opd_032_prospective_state_ledger.jsonl"\n\ndef observe(snapshot,root=None):\n    root=Path(root or Path.cwd());rt,ledger=_paths(root);freeze=json.loads((rt/"opd_031_prospective_candidate_freeze.json").read_text())\n    if FORBIDDEN.intersection(snapshot):raise ValueError("POST_T_OR_OUTCOME_FIELD_REJECTED")\n    req=("anchor_id","ticker","observed_epoch","horizon_seconds","tokens")\n    if any(k not in snapshot for k in req):raise ValueError("MISSING_REQUIRED_STATE_FIELD")\n    if float(snapshot["observed_epoch"])<=float(freeze["activation_epoch"]):raise ValueError("PRE_FREEZE_STATE_REJECTED")\n    toks=set(snapshot["tokens"]);h=int(snapshot["horizon_seconds"]);matches=[]\n    for c in freeze["candidates"]:\n        if int(c["horizon_seconds"])==h and all(t in toks for t in c["formula"]):matches.append(c["family_id"])\n    state_id=hashlib.sha256(_canon([snapshot["anchor_id"],snapshot["ticker"],snapshot["observed_epoch"],h]).encode()).hexdigest()\n    row={"state_id":state_id,"anchor_id":snapshot["anchor_id"],"ticker":snapshot["ticker"],\n         "observed_epoch":float(snapshot["observed_epoch"]),"horizon_seconds":h,"tokens":sorted(toks),\n         "anchor_price":snapshot.get("anchor_price"),"matched_family_ids":matches,"post_freeze":True,\n         "anchor_sequence_boundary":snapshot.get("anchor_sequence_boundary"),\n         "anchor_sequence_basis":snapshot.get("anchor_sequence_basis")}\n    seen=set()\n    if ledger.exists():\n        with ledger.open(encoding="utf-8") as f:\n            for line in f:\n                try:seen.add(json.loads(line)["state_id"])\n                except:pass\n    if state_id not in seen:\n        with ledger.open("a",encoding="utf-8") as f:f.write(_canon(row)+"\\n")\n    return row\n\ndef summary(root=None):\n    root=Path(root or Path.cwd());rt,ledger=_paths(root);rows=[]\n    if ledger.exists():\n        with ledger.open(encoding="utf-8") as f:rows=[json.loads(x) for x in f if x.strip()]\n    s={"schema_version":"OPD-032","states":len(rows),"trigger_states":sum(bool(x["matched_family_ids"]) for x in rows),\n       "unique_tickers":len({x["ticker"] for x in rows}),"all_post_freeze":all(x["post_freeze"] for x in rows),"execution_authority":False}\n    out=rt/"opd_032_prospective_state_intake_ledger.json";out.write_text(json.dumps(s,indent=2,sort_keys=True));return s,out\n'
files['qseries_v2/oracle_predictive_data/opd_039_durable_horizon_maturity_queue.py']='from pathlib import Path\nimport hashlib,json,time\n\ndef rebuild(root=None):\n    root=Path(root or Path.cwd());rt=root/"runtime"/"predictive_data";src=rt/"opd_032_prospective_state_ledger.jsonl";done=rt/"opd_033_prospective_outcome_ledger.jsonl";dst=rt/"opd_039_maturity_queue.json"\n    resolved=set()\n    if done.exists():\n        with done.open(encoding="utf-8") as f:\n            for line in f:\n                if line.strip():resolved.add(json.loads(line)["state_id"])\n    pending=[]\n    if src.exists():\n        with src.open(encoding="utf-8") as f:\n            for line in f:\n                if not line.strip():continue\n                x=json.loads(line)\n                if x["state_id"] in resolved:continue\n                pending.append({"state_id":x["state_id"],"anchor_id":x.get("anchor_id"),"ticker":x["ticker"],\n                                "observed_epoch":x["observed_epoch"],"horizon_seconds":x["horizon_seconds"],\n                                "maturity_epoch":float(x["observed_epoch"])+int(x["horizon_seconds"]),\n                                "anchor_price":x.get("anchor_price"),"matched_family_ids":x["matched_family_ids"],\n                                "anchor_sequence_boundary":x.get("anchor_sequence_boundary"),\n                                "anchor_sequence_basis":x.get("anchor_sequence_basis")})\n    pending.sort(key=lambda x:(x["maturity_epoch"],x["state_id"]));dst.write_text(json.dumps(pending,indent=2,sort_keys=True))\n    now=time.time();s={"schema_version":"OPD-039","pending":len(pending),"mature_now":sum(x["maturity_epoch"]<=now for x in pending),\n       "queue_hash":hashlib.sha256(dst.read_bytes()).hexdigest(),"restart_rebuildable":True,"duplicate_resolution_prevented":True,"execution_authority":False}\n    out=rt/"opd_039_durable_horizon_maturity_queue.json";out.write_text(json.dumps(s,indent=2,sort_keys=True));return s,out\n\ndef mature(root=None,now=None):\n    root=Path(root or Path.cwd());rt=root/"runtime"/"predictive_data";p=rt/"opd_039_maturity_queue.json"\n    rows=json.loads(p.read_text()) if p.exists() else [];t=float(now if now is not None else time.time());return [x for x in rows if x["maturity_epoch"]<=t]\n'
files['qseries_v2/oracle_predictive_discovery/opd_056_highwater_witnessed_future_outcome.py']='from pathlib import Path\nfrom qseries_v2.oracle_predictive_discovery.opd_055_event_time_highwater_coverage import read_until_witness\nfrom qseries_v2.oracle_predictive_discovery.opd_051_exact_witnessed_future_path_outcome import materialize_from_path_and_witness\nfrom qseries_v2.oracle_production_hardening.oph_019_postgresql_universal_ingestion_queue import connect\nfrom qseries_v2.oracle_predictive_discovery.opd_046_exact_kalshi_future_price_materializer import SOURCE\nexecution_authority=False\nprobability_enabled=False\ndirection_enabled=False\npublication_allowed=False\n\ndef _highwater_at_or_before(state,root=None):\n    root=Path(root or Path.cwd());t=float(state["observed_epoch"])\n    with connect(root,autocommit=False) as c:\n        with c.cursor() as q:\n            q.execute("SET TRANSACTION READ ONLY")\n            q.execute("SET LOCAL statement_timeout=\'5000ms\'")\n            q.execute("SELECT sequence_number FROM public.oracle_canonical_observations WHERE observed_at<=to_timestamp(%s) ORDER BY observed_at DESC,sequence_number DESC LIMIT 1",(t,))\n            row=q.fetchone()\n        c.rollback()\n    return int(row[0]) if row else None\n\ndef exact_anchor_sequence(state,root=None):\n    explicit=state.get("anchor_sequence_boundary")\n    if explicit is not None:\n        try:return int(explicit)\n        except Exception:pass\n    aid=str(state.get("anchor_id") or "").strip()\n    root=Path(root or Path.cwd())\n    if aid:\n        with connect(root,autocommit=False) as c:\n            with c.cursor() as q:\n                q.execute("SET TRANSACTION READ ONLY")\n                q.execute("SET LOCAL statement_timeout=\'5000ms\'")\n                q.execute("SELECT sequence_number FROM public.oracle_canonical_observations WHERE source_id=%s AND observation_id=%s ORDER BY sequence_number DESC LIMIT 1",(SOURCE,aid))\n                row=q.fetchone()\n            c.rollback()\n        if row:return int(row[0])\n    return _highwater_at_or_before(state,root)\n\ndef materialize_live(state,root=None,after_sequence=None):\n    start=exact_anchor_sequence(state,root) if after_sequence is None else int(after_sequence)\n    if start is None:return None\n    end=float(state["observed_epoch"])+int(state["horizon_seconds"])\n    path,witness,highwater=read_until_witness(state["ticker"],state["observed_epoch"],end,root,start,2000,16)\n    out=materialize_from_path_and_witness(state,path,witness)\n    if out is not None:\n        out["coverage_start_sequence"]=int(start)\n        out["coverage_highwater_sequence"]=int(highwater)\n        out["anchor_sequence_exact"]=True\n        out["anchor_sequence_basis"]=state.get("anchor_sequence_basis") or "CANONICAL_HIGHWATER_AT_OR_BEFORE_FROZEN_TIME"\n    return out\n'
test_code='from pathlib import Path\nfrom qseries_v2.oracle_predictive_discovery import opd_056_highwater_witnessed_future_outcome as m56\nimport qseries_v2.oracle_predictive_discovery.opd_042_live_state_to_prospective_intake_bridge as m42\n\nm42.materialize_exact_live_tokens=lambda root,s:("H:5",)\ns={"anchor_id":"a","ticker":"KXBTC","observed_epoch":100.0,"horizon_seconds":5,"anchor_price":.5,\n   "kalshi_state":{},"coinbase_hf_state":{},"crypto_condition_state":{},"learned_state":None,\n   "anchor_sequence_boundary":123,"anchor_sequence_basis":"CANONICAL_HIGHWATER_AT_FREEZE"}\nz=m42.snapshot_from_world_state(s,Path.cwd())\nassert z["anchor_sequence_boundary"]==123\nassert z["anchor_sequence_basis"]=="CANONICAL_HIGHWATER_AT_FREEZE"\nassert m56.exact_anchor_sequence({"anchor_sequence_boundary":456,"observed_epoch":100.0},Path.cwd())==456\nassert m56.execution_authority is False\nprint("[PASS] anchor boundary is stamped, carried, and preferred without future leakage")\nprint("[EXECUTION/PROBABILITY/DIRECTION/PUBLICATION] FALSE/FALSE/FALSE/FALSE")\n'
